mockup.css:
.mock-hero-colour-block-grid { display: grid; grid-template-columns: 34% 24% 1fr; grid-template-rows: 56% 1fr;
  background: #f0ebdf; color: #17150f; font-family: "Inter", ui-sans-serif, sans-serif; }
.mock-hero-colour-block-grid .b { padding: 3.4cqw; display: flex; }
.mock-hero-colour-block-grid .b1 { grid-column: 1 / 3; background: #b23a1e; color: #fdf6ea; align-items: flex-end; }
.mock-hero-colour-block-grid .b1 h4 { margin: 0; font-size: 4.6cqw; line-height: 1.02; font-weight: 750; letter-spacing: -.03em; }
.mock-hero-colour-block-grid .b2 { grid-column: 3; grid-row: 1 / 3; }
.mock-hero-colour-block-grid .b3 { grid-column: 1; background: #17324a; color: #e7eef3; align-items: flex-end; }
.mock-hero-colour-block-grid .b3 span { font-size: 1.7cqw; letter-spacing: .12em; text-transform: uppercase; }
.mock-hero-colour-block-grid .b4 { grid-column: 2; flex-direction: column; justify-content: flex-end; gap: 1.6cqw; }
.mock-hero-colour-block-grid .b4 p { margin: 0; font-size: 1.9cqw; line-height: 1.35; }
